#!/usr/bin/env ruby
# frozen_string_literal: true

# Composes the ebook cover: fits the (label-free) cover art to 1600x2560
# (KDP's recommended ebook cover, 1:1.6), then sets title, subtitle and author
# as real type, so text is never generated by the image model.
#   title:    Limelight (OFL), art deco display face
#   subtitle/author: Source Sans 3 (OFL), the book's heading face
#
# Usage: scripts/compose_cover.rb ART OUT [--lang pt]
# Text comes from book/outline.yml (meta.working_title / subtitle / author).

require "yaml"

ROOT = File.expand_path("..", __dir__)
art, out = ARGV[0], ARGV[1]
abort "usage: compose_cover.rb ART OUT" unless art && out
meta = YAML.load_file(File.join(ROOT, "book", "outline.yml"))["meta"]
lang = ARGV.include?("--lang") ? ARGV[ARGV.index("--lang") + 1] : "pt"
suffix = lang == "pt" ? "" : "_#{lang}"
fonts = File.join(ROOT, "assets", "fonts")
W, H = 1600, 2560
CREAM = "#F4E9D0"
SHADOW = "#0B1A26"

# Title broken where the words land well on a poster: "COMPETENTE / O SUFICIENTE".
words = (meta["working_title#{suffix}"] || meta["working_title"]).upcase.split
title = words.size > 2 ? "#{words.first}\n#{words[1..].join(' ')}" : words.join("\n")
subtitle = (meta["subtitle#{suffix}"] || meta["subtitle"]).to_s.sub(/,\s*/, ",\n")
author = meta["author"].to_s.upcase

def text_layer(font:, size:, text:, gravity:, offset:, kerning: 0, interline: 0)
  ["(", "-size", "#{W}x#{H}", "xc:none", "-font", font, "-pointsize", size.to_s, "-kerning", kerning.to_s,
   "-interline-spacing", interline.to_s, "-gravity", gravity,
   "-fill", SHADOW, "-annotate", "+#{offset[0] + 6}+#{offset[1] + 8}", text, "-blur", "0x10",
   "-fill", CREAM, "-annotate", "+#{offset[0]}+#{offset[1]}", text, ")", "-composite"]
end

cmd = ["magick", art, "-resize", "#{W}x#{H}^", "-gravity", "center", "-extent", "#{W}x#{H}",
       # a gentle darkening behind the title keeps it legible on bright skies
       "(", "-size", "#{W}x900", "gradient:#0B1A26B0-#0B1A2600", ")", "-gravity", "north", "-composite",
       *text_layer(font: "#{fonts}/Limelight-Regular.ttf", size: 190, text: title, gravity: "north", offset: [0, 150], kerning: 4, interline: -10),
       # Footer block: subtitle above the author, both on a dark gradient, so the
       # title area at the top stays clear of the art's focal point (the robot head).
       "(", "-size", "#{W}x640", "gradient:#0B1A2600-#0B1A26D8", ")", "-gravity", "south", "-composite",
       *text_layer(font: "#{fonts}/SourceSans3-Semibold.otf", size: 54, text: subtitle, gravity: "south", offset: [0, 250], kerning: 2),
       *text_layer(font: "#{fonts}/SourceSans3-Bold.otf", size: 78, text: author, gravity: "south", offset: [0, 110], kerning: 18),
       "-alpha", "remove", "-alpha", "off", "-colorspace", "sRGB", "-quality", "95", out]
system(*cmd, exception: true)
warn "wrote #{out}"
